export function itemByNo(itemNo: string): NavItem {
  const item = ITEMS.find((candidate) => candidate.itemNo === itemNo);
  if (!item) throw new Error(`Sample data refers to an unknown item: ${itemNo}`);
  return item;
}

export function customerByName(name: string): NavCustomer {
  const customer = CUSTOMERS.find((candidate) => candidate.name === name);
  if (!customer) throw new Error(`Sample data refers to an unknown customer: ${name}`);
  return customer;
}

export function vendorByName(name: string): NavVendor {
  const vendor = VENDORS.find((candidate) => candidate.name === name);
  if (!vendor) throw new Error(`Sample data refers to an unknown vendor: ${name}`);
  return vendor;
}
